// Generated by build-sw.mjs. Only public, versioned shell files are cached.
const version = '__CACHE_VERSION__'
const precache = ['__PRECACHE__']
const shellCache = `robopark-shell-${version}`
const runtimeCache = `robopark-runtime-${version}`
const shellCachePrefix = 'robopark-shell-'
const runtimeCachePrefix = 'robopark-runtime-'
const maxRuntimeEntries = 100
const hashedAsset = /^\/assets\/(?:[A-Za-z0-9_-]+\/)*[A-Za-z0-9_-]+-[A-Za-z0-9_-]{2,}\.(?:js|css|png|svg|webp|woff2?)$/

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(shellCache)
    await cache.addAll(precache)
    const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
    clients.forEach((client) => client.postMessage({ type: 'UPDATE_READY' }))
  })())
  // Do not call skipWaiting: an open page must keep using its existing bundle.
})

self.addEventListener('message', (event) => {
  if (event.data?.type !== 'ACTIVATE_WHEN_SAFE') return
  const state = event.data.state
  if (state?.status !== 'idle' || state.pending !== 0 || state.conflicts !== 0) return
  event.waitUntil((async () => {
    try {
      if (await localWorkSettled() && await openClientsSafe()) await self.skipWaiting()
    } catch {
      // Keep the old shell when local work cannot be inspected.
    }
  })())
})

async function openClientsSafe() {
  const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
  return (await Promise.all(clients.map(client => new Promise(resolve => {
    const channel = new MessageChannel()
    const timeout = setTimeout(() => finish(false), 2000)
    function finish(safe) {
      clearTimeout(timeout)
      channel.port1.close()
      channel.port2.close()
      resolve(safe)
    }
    channel.port1.onmessage = event => finish(event.data?.safe === true)
    try { client.postMessage({ type: 'CHECK_ACTIVATION_SAFETY' }, [channel.port2]) }
    catch { finish(false) }
  })))).every(Boolean)
}

function localWorkSettled() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') { reject(new Error('indexeddb_unavailable')); return }
    const request = indexedDB.open('robopark-offline')
    let missing = false
    request.onupgradeneeded = () => {
      missing = true
      request.transaction.abort()
    }
    request.onerror = () => missing ? resolve(true) : reject(request.error)
    request.onsuccess = () => {
      const db = request.result
      if (!db.objectStoreNames.contains('actions') || !db.objectStoreNames.contains('media')) {
        db.close()
        reject(new Error('offline_stores_unavailable'))
        return
      }
      const transaction = db.transaction(['actions', 'media'], 'readonly')
      const actions = transaction.objectStore('actions')
      const media = transaction.objectStore('media')
      const actionCount = actions.count()
      const confirmedActions = actions.index('state').count('confirmed')
      const cancelledActions = actions.index('state').count('cancelled')
      const mediaCount = media.count()
      const confirmedMedia = media.index('state').count('confirmed')
      transaction.oncomplete = () => {
        db.close()
        resolve(actionCount.result === confirmedActions.result + cancelledActions.result
          && mediaCount.result === confirmedMedia.result)
      }
      transaction.onerror = transaction.onabort = () => { db.close(); reject(transaction.error) }
    }
  })
}

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys()
    await Promise.all(names.filter((name) => (name.startsWith(shellCachePrefix) || name.startsWith(runtimeCachePrefix)) && name !== shellCache && name !== runtimeCache)
      .map((name) => caches.delete(name)))
    await self.clients.claim()
  })())
})

self.addEventListener('push', (event) => {
  let eventId = 'event'
  try { eventId = event.data?.json()?.event_id || eventId } catch { /* malformed payload */ }
  event.waitUntil(self.registration.showNotification('Новое событие', {
    body: 'Откройте приложение, чтобы посмотреть подробности.',
    tag: `robopark-${eventId}`,
    data: { url: '/schedule' },
  }))
})

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  event.waitUntil((async () => {
    const url = new URL(event.notification.data?.url || '/', self.location.origin).href
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
    const existing = windows[0]
    if (existing) {
      await existing.navigate(url)
      return existing.focus()
    }
    return self.clients.openWindow(url)
  })())
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  const url = new URL(request.url)
  if (request.method === 'POST' && url.origin === self.location.origin && url.pathname === '/share-target') {
    event.respondWith(storeSharedPhoto(request))
    return
  }
  if (request.method !== 'GET') return
  if (url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return

  if (request.mode === 'navigate') {
    const shell = caches.open(shellCache).then(async (cache) => {
      const refresh = fetch('/index.html', { cache: 'no-store' }).then(async (response) => {
        if (response.ok && response.type !== 'opaque') await cache.put('/index.html', response.clone())
        return response
      })
      event.waitUntil(refresh.then(() => undefined).catch(() => undefined))
      return (await cache.match('/index.html')) ?? refresh.catch(() => cache.match('/offline.html'))
    })
    event.respondWith(shell)
    return
  }
  if (url.search || !hashedAsset.test(url.pathname)) return
  event.respondWith((async () => {
    const cached = await caches.match(request)
    if (cached) return cached
    const response = await fetch(request)
    const contentType = response.headers.get('content-type') || ''
    if (response.ok && response.type !== 'opaque' && /^(?:text\/css|(?:application|text)\/javascript|image\/(?:png|svg\+xml|webp)|font\/woff2?)/i.test(contentType)) {
      const cache = await caches.open(runtimeCache)
      await cache.put(request, response.clone())
      const keys = await cache.keys()
      await Promise.all(keys.slice(0, Math.max(0, keys.length - maxRuntimeEntries)).map((key) => cache.delete(key)))
    }
    return response
  })())
})

function openShareInbox() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('robopark-share-inbox', 1)
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains('drafts')) request.result.createObjectStore('drafts', { keyPath: 'id' })
    }
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error)
  })
}

async function storeSharedPhoto(request) {
  try {
    const form = await request.formData()
    const photo = form.get('photo')
    if (photo instanceof Blob && photo.type.startsWith('image/') && photo.size <= 15 * 1024 * 1024) {
      const db = await openShareInbox()
      const transaction = db.transaction('drafts', 'readwrite')
      transaction.objectStore('drafts').put({
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        name: photo.name || 'shared-photo',
        type: photo.type,
        blob: photo,
        assignment: null,
      })
      await new Promise((resolve, reject) => {
        transaction.oncomplete = resolve
        transaction.onerror = () => reject(transaction.error)
        transaction.onabort = () => reject(transaction.error)
      })
      db.close()
    }
  } catch {
    // Opening the application is still useful when the shared file cannot be stored.
  }
  return Response.redirect(`${self.location.origin}/?shared=1`, 303)
}
